update public.classes set description = 'A gentle first swim in a warm pool. Parents hold their babies through songs, floating and splashing, so little ones get comfortable with water. Small groups of 6, with one instructor guiding each step.', focus = 'Water comfort, floating with support, bonding', what_to_bring = 'Swim diapers, towel, a snack for after', first_visit = 'Arrive 10 minutes early. Parents get in the water too, so bring a swimsuit.', instructor = 'Ms. Dana', instructor_bio = '10 years teaching babies to swim, infant CPR certified' where title = 'Water Babies Intro';
update public.classes set description = 'Toddlers build water confidence with songs and games: kicking, blowing bubbles and short, supported glides. Fun, low pressure and never forced. Small groups with a parent in the water.', focus = 'Kicking, blowing bubbles, safe water habits', what_to_bring = 'Swim diapers, towel, goggles optional', first_visit = 'Arrive 10 minutes early. The first class is a gentle introduction and no one has to get their face wet.', instructor = 'Mr. Luis', instructor_bio = 'Former lifeguard, 8 years with toddlers' where title = 'Toddler Splash';
update public.classes set description = 'Beginner swim for young kids who are ready to learn with an instructor, with a parent close by. Kids practice floating, kicking and moving through the water, one small skill at a time.', focus = 'Floating, kicking, moving through water', what_to_bring = 'Swimsuit, towel, goggles', first_visit = 'Arrive 10 minutes early to check in. Children shower before the class.', instructor = 'Coach Maya', instructor_bio = 'Certified swim instructor, 6 years with kids ages 1 to 3' where title = 'Little Fins';
